  egypt_unify: { n: 'Unification de l’Égypte', p: 'Memphis, Égypte', d: 'Narmer unifie la Haute et la Basse-Égypte et fonde l’un des États les plus durables de l’histoire du monde.' },
  indus_civ: { n: 'Civilisation de la vallée de l’Indus', p: 'Mohenjo-daro, vallée de l’Indus', d: 'Des villes au plan en damier, dotées d’égouts et de poids étalonnés, s’épanouissent dans la vallée de l’Indus — aussi urbaines que l’Égypte ou Sumer, et encore largement indéchiffrées.' },
  trypillia: { n: 'Les mégasites tripoliens', p: 'Talianky, Ukraine', d: 'Les cultivateurs cucuténo-tripoliens de l’actuelle Ukraine bâtissent les plus grandes agglomérations de leur temps — Talianky abrite peut-être 15 000 personnes sur des centaines d’hectares, 5 000 ans avant Kyiv.' },
  giza_pyramid: { n: 'Construction de la grande pyramide de Gizeh', p: 'Gizeh, Égypte', d: 'La pyramide de Khéops — 146 m de haut, la plus haute construction humaine pendant 3 800 ans — s’élève sur la rive occidentale du Nil.' },
