  caral: { n: 'Civilisation de Caral-Supe', p: 'Caral, Pérou', d: 'La plus ancienne ville connue d’Amérique prospère sur la côte péruvienne avec ses pyramides monumentales — ni poterie ni trace de guerre, mais des cordes à nœuds semblables aux quipus.' },
  akkad: { n: 'Empire d’Akkad — le premier empire', p: 'Akkad, Mésopotamie', d: 'Sargon d’Akkad forge le premier empire multiethnique de l’histoire, qui s’étend du golfe Persique à la Méditerranée.' },
  gilgamesh: { n: 'L’Épopée de Gilgamesh', p: 'Uruk, Mésopotamie', d: 'La plus ancienne grande littérature parvenue jusqu’à nous est composée en sumérien : elle raconte la quête d’immortalité d’un roi.' },
  shang: { n: 'Dynastie Shang', p: 'Anyang, Chine', d: 'Première dynastie chinoise confirmée par l’archéologie, célèbre pour ses bronzes et son écriture sur os oraculaires — l’ancêtre de l’écriture chinoise.' },
  minoan: { n: 'Civilisation minoenne', p: 'Cnossos, Crète', d: 'La première grande civilisation d’Europe domine la mer Égée depuis le palais de Cnossos, avec ses fresques éclatantes et une écriture encore indéchiffrée.' },
  hammurabi: { n: 'Code de Hammurabi', p: 'Babylone', d: 'Hammurabi promulgue l’un des plus anciens codes juridiques déchiffrés : 282 lois gravées sur une stèle de pierre — « œil pour œil ».' },
  bronze_collapse: { n: 'Effondrement de l’âge du bronze récent', p: 'Méditerranée orientale', d: 'En quelques décennies, les économies palatiales de Mycènes à Ougarit s’effondrent — sécheresse, famine, séismes et l’énigme des « Peuples de la mer ».' },
  troy: { n: 'Guerre de Troie (date traditionnelle)', p: 'Troie, Anatolie', d: 'Légende et archéologie se confondent : une guerre pour Hélène de Troie, immortalisée plus tard par Homère, au moment même où le monde de l’âge du bronze se désagrège.' },
  phoenician_alpha: { n: 'Alphabet phénicien', p: 'Byblos, Phénicie', d: 'Les marchands phéniciens forgent un alphabet consonantique de 22 lettres — l’ancêtre du grec, du latin, de l’arabe, de l’hébreu et de la plupart des écritures actuelles.' },
