  kush: { n: 'Royaume de Koush', p: 'Méroé, Nubie', d: 'Le royaume nubien de Koush domine le haut Nil pendant plus d’un millénaire — conquérant parfois l’Égypte elle-même — et dresse ses propres pyramides à Méroé.' },
  olmec: { n: 'Civilisation olmèque', p: 'La Venta, Mexique', d: 'La « culture-mère » de la Mésoamérique sculpte des têtes colossales de pierre et pose des rites que hériteront plus tard les Mayas et les Aztèques.' },
  zhou: { n: 'Dynastie Zhou', p: 'Haojing, Chine', d: 'La plus longue dynastie chinoise introduit le « Mandat du ciel », tandis que ses derniers siècles voient naître Confucius, Laozi et les Cent Écoles de pensée.' },
  assyria: { n: 'Empire néo-assyrien', p: 'Ninive, Assyrie', d: 'La première véritable superpuissance : armées de fer, déportations massives et la grande bibliothèque d’Assurbanipal font de l’Assyrie la maîtresse du Moyen-Orient.' },
  new_kingdom_ramses: { n: 'Ramsès II', p: 'Thèbes, Égypte', d: 'Le plus grand pharaon d’Égypte règne 66 ans, affronte les Hittites à Qadesh et fait bâtir Abou Simbel.' },
  olympics: { n: 'Premiers jeux Olympiques', p: 'Olympie, Grèce', d: 'Les cités grecques suspendent leurs guerres tous les quatre ans tandis que les athlètes s’affrontent nus à Olympie en l’honneur de Zeus.' },
  rome_founded: { n: 'Fondation de Rome', p: 'Rome', d: 'Date traditionnelle de la fondation de Rome par Romulus sur le mont Palatin — un village destiné à dominer le monde méditerranéen.' },
  homer: { n: 'Homère compose l’Iliade et l’Odyssée', p: 'Ionie (Smyrne)', d: 'Barde aveugle ou tradition de bardes — toujours est-il que la pierre angulaire de la littérature occidentale est posée sur la côte d’Asie Mineure.' },
  scythia: { n: 'Royaume scythe', p: 'Steppe du bas-Dnipro, Ukraine', d: 'Ces nomades cavaliers qu’interroge Hérodote dominent la steppe ukrainienne et vendent leur blé à Athènes ; leurs kourganes royaux livrent encore des chefs-d’œuvre d’or, comme la célèbre Pectorale.' },
  buddha: { n: 'Siddhartha Gautama — le Bouddha', p: 'Bodh Gaya, Inde', d: 'Un prince du clan Shakya atteint l’éveil sous l’arbre Bodhi et enseigne la Voie moyenne, fondant l’une des grandes religions du monde.' },
  confucius: { n: 'Confucius', p: 'Qufu, Chine', d: 'Le penseur le plus influent de Chine enseigne une éthique de loyauté familiale, de rite et de pouvoir bienveillant — des idées qui façonnent encore l’Asie de l’Est.' },
  achaemenid: { n: 'Empire perse achéménide', p: 'Persépolis, Perse', d: 'Cyrus le Grand fonde le plus vaste empire jamais vu ; ses successeurs bâtissent Persépolis et tolèrent les religions locales — dont le retour des Juifs à Jérusalem.' },
  temple_destroyed: { n: 'Nebucadnetsar détruit Jérusalem', p: 'Jérusalem', d: 'Les armées babyloniennes incendient le Temple de Salomon et déportent l’élite de Juda à Babylone — c’est l’exil à Babylone.' },
