  salamis: { n: 'Apogée des guerres médiques', p: 'Thermopyles et Salamine', d: 'Les 300 de Léonidas tombent aux Thermopyles, puis la flotte grecque détruit celle de Xerxès à Salamine — la Grèce classique est sauvée.' },
  bosporan: { n: 'Royaume du Bosphore', p: 'Panticapée (Kertch)', d: 'Ce royaume sous domination grecque, à cheval sur les deux rives du détroit de Kertch, devient le client le plus oriental de Rome — et la grande artère du commerce entre la steppe et la mer Noire.' },
  warring_states: { n: 'Période des Royaumes combattants', p: 'Chine', d: 'Sept royaumes chinois se livrent pendant 250 ans une guerre d’extermination qui déclenche une course aux armements philosophique, tactique et technologique — dont les Qin sortent vainqueurs.' },
  socrates: { n: 'Socrate', p: 'Athènes', d: 'Le taon d’Athènes interroge tout, est jugé pour « corruption de la jeunesse » et meurt par le poison — enseignant la philosophie par l’exemple.' },
  plato: { n: 'Platon', p: 'Athènes', d: 'L’élève de Socrate fonde l’Académie — le prototype de l’université — et écrit des dialogues qui façonnent la pensée occidentale depuis 2 400 ans.' },
  chersonesus: { n: 'Fondation de Chersonèse', p: 'Chersonèse (Sébastopol)', d: 'Des colons grecs d’Héraclée du Pont fondent une polis démocratique sur la côte sud-ouest de la Crimée ; elle cultivera le littoral pendant deux millénaires et frappera sa propre monnaie.' },
  aristotle: { n: 'Aristote', p: 'Athènes et Pella', d: 'Précepteur d’Alexandre et fondateur du Lycée, il systématise la logique, la biologie, l’éthique et la politique — « le maître de ceux qui savent ».' },
  alexander: { n: 'Alexandre le Grand', p: 'Pella, Macédoine', d: 'En 13 ans, le jeune Macédonien conquiert un espace allant de la Grèce à l’Inde, diffuse la culture hellénistique et meurt à 32 ans à Babylone.' },
  hellenistic: { n: 'Les conquêtes d’Alexandre', p: 'Macédoine → Inde', d: 'Langue, art et science grecs fusionnent avec l’Orient, du Nil à l’Indus, faisant germer le monde hellénistique.' },
  euclid: { n: 'Les Éléments d’Euclide', p: 'Alexandrie', d: 'Le manuel le plus influent jamais écrit systématise la géométrie à partir de cinq axiomes — un ouvrage encore utilisé au XXe siècle.' },
  library_alexandria: { n: 'Bibliothèque d’Alexandrie', p: 'Alexandrie, Égypte', d: 'Les Lagides tentent de rassembler tous les livres du monde ; la grande bibliothèque fait d’Alexandrie la capitale scientifique de la Méditerranée pendant des siècles.' },
  maurya: { n: 'Empire maurya', p: 'Pataliputra, Inde', d: 'Chandragupta Maurya unit pour la première fois l’essentiel de l’Asie du Sud ; son ministre Chanakya rédige l’Arthashastra, machiavélique 1 700 ans avant Machiavel.' },
  ashoka: { n: 'Ashoka le Grand', p: 'Pataliputra, Inde', d: 'Après le carnage de Kalinga, le plus grand empereur de l’Inde embrasse le bouddhisme et fait graver des édits de tolérance religieuse à travers tout le sous-continent.' },
  kalinga: { n: 'Ashoka se convertit au bouddhisme', p: 'Kalinga, Inde', d: 'Horrifié par sa propre conquête sanglante du Kalinga, Ashoka devient bouddhiste et envoie des missionnaires jusqu’en Égypte et en Grèce.' },
