  qin_shi_huang: { n: 'Qin Shi Huang', p: 'Xianyang, Chine', d: 'Le premier empereur de Chine met fin aux Royaumes combattants, unifie écriture, poids et essieux — et se fait enterrer avec son armée en terre cuite.' },
  qin_unify: { n: 'Unification de la Chine', p: 'Xianyang, Chine', d: '« Tout ce qui est sous le ciel » est réuni sous un seul empereur — le début de 2 000 ans de Chine impériale.' },
  terracotta: { n: 'Armée en terre cuite', p: 'Xi’an, Chine', d: 'Des milliers de soldats d’argile grandeur nature, tous uniques, montent la garde devant la tombe du premier empereur — découverte par des paysans creusant un puits en 1974.' },
  great_wall: { n: 'Début de la Grande Muraille', p: 'Nord de la Chine', d: 'Les ingénieurs des Qin relient d’anciens remparts en une « muraille de 10 000 li » face aux pillards nomades.' },
  punic2: { n: 'Deuxième guerre punique — Hannibal', p: 'Alpes et Italie', d: 'Hannibal fait passer des éléphants de guerre par les Alpes et ravage l’Italie pendant 15 ans, écrasant Rome à Cannes — mais Carthage finit par perdre.' },
  archimedes: { n: 'Archimède', p: 'Syracuse, Sicile', d: 'Le plus grand mathématicien de l’Antiquité calcule π, la poussée (« Eurêka ! ») et les leviers — tué par un soldat romain alors qu’il traçait des figures de géométrie.' },
