  thessalonica: { n: 'Le christianisme devient religion d’État de Rome', p: 'Thessalonique', d: 'L’édit de Thessalonique fait du christianisme nicéen la foi officielle de l’empire et interdit les cultes païens.' },
  attila: { n: 'Attila, roi des Huns', p: 'Pannonie', d: 'Le « fléau de Dieu » extorque et brûle de Constantinople à la Gaule, jusqu’à ce que son empire s’éteigne avec lui.' },
  rome_falls: { n: 'Chute de l’Empire romain d’Occident', p: 'Ravenne', d: 'Odoacre dépose le dernier empereur d’Occident — la fin conventionnelle de l’Antiquité en Occident.' },
  gupta: { n: 'Empire gupta', p: 'Pataliputra, Inde', d: 'L’âge d’or classique de l’Inde : la poésie de Kalidasa, le Kâmasûtra, les mathématiques décimales et le concept de zéro.' },
  aryabhata: { n: 'Aryabhata', p: 'Kusumapura, Inde', d: 'Il calcule π avec quatre décimales, la rotation de la Terre et la durée de l’année avec une précision étonnante — à 23 ans.' },
  maya_classic: { n: 'Période classique maya', p: 'Tikal, Guatemala', d: 'Les cités-États de pyramides-temples et d’écriture hiéroglyphique atteignent leur apogée, Tikal et Calakmul rivalisant en superpuissances.' },
  teotihuacan: { n: 'Teotihuacan', p: 'Teotihuacan, Mexique', d: 'La première métropole d’Amérique — plus de 100 000 habitants le long de l’allée des Morts — exporte art, dieux et influence à travers toute la Mésoamérique.' },
