  linnaeus: { n: 'Carl Linné', p: 'Uppsala, Suède', d: 'Il nomme tout : le système binomial (Systema Naturae, 1735) donne à chaque être vivant deux mots latins — et rend la biologie possible.' },
  voltaire: { n: 'Voltaire', p: 'Paris', d: 'L’esprit comme arme : le philosophe qui combattit « l’infâme » — fanatisme d’Église et censure — et rendit la pensée à la mode.' },
