  hrushevsky: { n: 'Mykhaïlo Hrouchevsky', p: 'Kyiv', d: 'Son « Histoire de l’Ukraine-Rus’ » en dix volumes rendit la Rus’ de Kyiv à l’histoire ukrainienne — la réponse savante à l’école impériale qui l’avait annexée au passé russe ; en 1917, il préside le premier parlement d’Ukraine, la Rada centrale, et meurt en exil soviétique.' },
  opium_war: { n: 'Première guerre de l’opium', p: 'Canton, Chine', d: 'La Grande-Bretagne se bat pour continuer à vendre de l’opium à la Chine — et gagne Hong Kong et les ports traités à coups de canonnières.' },
  taiping: { n: 'Révolte des Taiping', p: 'Nankin, Chine', d: 'Un maître d’école de village prétendant être le petit frère du Christ déclenche la guerre civile la plus sanglante de l’histoire — 20 millions de morts.' },
  suez: { n: 'Ouverture du canal de Suez', p: 'Suez, Égypte', d: 'La Méditerranée rencontre la mer Rouge : la route maritime des Indes raccourcit de 8 900 km.' },
  nz_suffrage: { n: 'Le suffrage féminin en Nouvelle-Zélande', p: 'Nouvelle-Zélande', d: 'La Nouvelle-Zélande devient le premier pays autogouverné où les femmes votent aux élections générales — la pétition de Kate Sheppard s’étire sur près de 1,6 km.' },
  panama_canal: { n: 'Ouverture du canal de Panama', p: 'Panama', d: 'Un canal de 77 km creusé dans la jungle, plus de 25 000 morts de maladie et de labeur — l’Atlantique et le Pacifique se serrent la main.' },
  wright: { n: 'Premier vol motorisé', p: 'Kitty Hawk, États-Unis', d: '12 secondes, 36 mètres — les frères Wright ouvrent l’ère de l’aviation sur une plage de Caroline battue par le vent.' },
  einstein: { n: 'Albert Einstein', p: 'Berne → Princeton', d: 'Commis aux brevets à Berne, célébrité à Berlin, sage de Princeton — la relativité, l’effet photoélectrique, E=mc².' },
  relativity: { n: 'La théorie de la relativité', p: 'Berne et Berlin', d: '1905 : la relativité restreinte et E=mc² ; 1915 : la gravité comme espace-temps courbé — les éclipses lui donnent raison en 1919.' },
  ww1: { n: 'Première Guerre mondiale', p: 'Sarajevo → monde entier', d: 'Les balles d’un assassin à Sarajevo défont un siècle d’empires : 20 millions de morts, le carnage des tranchées, un monde refait.' },
  russian_rev: { n: 'Révolution russe', p: 'Petrograd', d: '« Paix, terre, pain » — les Romanov tombent, les bolcheviks de Lénine s’emparent du pouvoir : le premier État socialiste du monde.' },
  unr: { n: 'La révolution ukrainienne de 1917-1921', p: 'Kyiv', d: 'De l’effondrement de deux empires naît la République populaire ukrainienne — la Rada de Hrouchevsky, Vynnychenko et Petlioura proclame l’indépendance en janvier 1918 et mène cinq ans de guerre ; vaincue, l’Ukraine est partagée entre la Russie soviétique, la Pologne, la Roumanie et la Tchécoslovaquie.' },
  estonia_1918: { n: 'L’Estonie déclare l’indépendance', p: 'Tallinn, Estonie', d: '24 février 1918 : le Comité de salut proclame la République ; la guerre d’indépendance suit — l’Armée rouge est battue à Võnnu en 1919, et la paix de Tartu de 1920 scelle le tout.' },
  latvia_1918: { n: 'La Lettonie déclare l’indépendance', p: 'Riga, Lettonie', d: '18 novembre 1918, au théâtre de Riga : un État pour un peuple dont les terres furent disputées pendant 700 ans par croisés, Polonais, Suédois et Russes.' },
  lithuania_1918: { n: 'La Lituanie restaure son État', p: 'Vilnius, Lituanie', d: '16 février 1918 : le Conseil de Lituanie vote l’Acte d’indépendance — le premier État lituanien moderne depuis le grand-duché ; Vilnius est prise par la Pologne en 1920, et Kaunas devient « capitale provisoire ».' },
  finland_1917: { n: 'La Finlande déclare l’indépendance', p: 'Helsinki, Finlande', d: '6 décembre 1917 : après 108 ans de grand-duché russe — et 560 ans de moitié orientale de la Suède — la Finlande devient une nation, et la Russie de Lénine la reconnaît la première.' },
  lenin: { n: 'Vladimir Lénine', p: 'Petrograd', d: 'Révolutionnaire professionnel en exil, puis chef d’État — il pilote le coup bolchevik et fonde l’URSS.' },
  spanish_flu: { n: 'Pandémie de grippe espagnole', p: 'Monde entier', d: 'Elle infecte un tiers de l’humanité et tue plus de gens (50 à 100 millions) que la Grande Guerre — surtout de jeunes adultes.' },
  versailles: { n: 'Traité de Versailles', p: 'Versailles', d: 'L’Allemagne est déclarée coupable, désarmée et condamnée à 132 milliards de marks-or — « un armistice pour vingt ans », prédit Foch.' },
  depression: { n: 'Grande Dépression', p: 'New York', d: 'Wall Street s’effondre et entraîne le monde : 25 % de chômage, des banques en faillite — et des dictatures qui montent.' },
  holodomor: { n: 'Holodomor', p: 'Ukraine', d: 'Réquisitions, listes noires et déportations staliniennes dépouillent les villages ukrainiens de leur grain pendant que l’État l’exporte ; la famine tue des millions — les études les plus souvent citées avancent 3,5 à 5 millions. L’Ukraine et de nombreux États la reconnaissent comme génocide.' },
  executed_renaissance: { n: 'La Renaissance exécutée', p: 'Kharkiv et Kyiv', d: 'L’éblouissante génération ukrainienne des années 1920 — la prose de Khvylovy, le théâtre Berezil de Kurbas, le néoclassicisme de Zerov — est anéantie par les arrestations massives ; en novembre 1937, des centaines d’écrivains, de savants et d’artistes de la république sont fusillés dans la clairière de Sandarmokh.' },
  ww2: { n: 'Seconde Guerre mondiale', p: 'Monde entier', d: 'Le conflit le plus meurtrier de l’histoire : 70 à 85 millions de morts, la Shoah, et un ordre du monde rebâti sur les cendres.' },
  soviet_baltic_occupation: { n: 'Occupation soviétique des pays baltes', p: 'Estonie · Lettonie · Lituanie', d: 'Protocole secret, ultimatum, annexion (1940) ; des dizaines de milliers de déportés vers la Sibérie dans des wagons à bestiaux en 1941 et 1949 ; les Frères de la forêt continuent le combat depuis les bois jusque dans les années 1950. L’occupation dure jusqu’en 1991.' },
  winter_war: { n: 'Guerre d’Hiver', p: 'Isthme de Carélie, Finlande', d: 'Staline envoie 450 000 hommes sur la Finlande en plein hiver arctique — et les Finlandais, à skis et cocktails Molotov, tiennent 105 jours ; des terres cédées, mais jamais conquis.' },
  holocaust: { n: 'La Shoah', p: 'Europe occupée', d: 'L’Allemagne nazie industrialise le génocide : six millions de Juifs, plus les Roms, les Slaves, les prisonniers politiques et d’autres encore, assassinés.' },
  wallenberg: { n: 'Raoul Wallenberg', p: 'Budapest, Hongrie', d: 'Le diplomate suédois qui remit à des dizaines de milliers de Juifs hongrois des passeports protecteurs et des maisons sûres — puis fut enlevé par les Soviétiques en 1945 et disparut dans la Loubianka ; déclaré mort en 1947.' },
  dday: { n: 'Jour J', p: 'Normandie, France', d: 'La plus grande invasion amphibie de tous les temps — 156 000 soldats alliés débarquent en France et commencent la libération de l’Europe occidentale.' },
  babi_yar: { n: 'Massacre de Babi Yar', p: 'Kyiv', d: 'Les 29-30 septembre 1941, l’Einsatzgruppe C fusille 33 771 Juifs de Kyiv dans le ravin de Babi Yar — l’un des plus grands massacres isolés de la Shoah ; pendant l’occupation, des dizaines de milliers d’autres y sont tués.' },
  upa: { n: 'Armée insurrectionnelle ukrainienne (UPA)', p: 'Ukraine occidentale', d: 'Armée de guérilla combattant pour un État ukrainien indépendant contre les forces soviétiques et allemandes — et impliquée dans le nettoyage ethnique de civils polonais en Volhynie (1943-1944), qui pèse encore sur la mémoire polono-ukrainienne. La traque soviétique dura jusque dans les années 1950.' },
