  sputnik: { n: 'Lancement de Spoutnik', p: 'Tiouratam, URSS', d: 'Une sphère métallique de 58 cm pépie au-dessus des têtes — l’ère spatiale commence, et l’Amérique panique jusqu’à créer la NASA.' },
  gagarin: { n: 'Gagarine orbite autour de la Terre', p: 'Baïkonour', d: '« Poïekhali ! » — 108 minutes qui font de Youri Gagarine le premier humain dans l’espace, pour toujours.' },
  everest: { n: 'Première ascension de l’Everest', p: 'Everest', d: 'Hillary et Tensing se tiennent au sommet du monde le 29 mai 1953 — la nouvelle atteint Londres le jour du couronnement.' },
  dna: { n: 'Découverte de la structure de l’ADN', p: 'Cambridge', d: 'Watson, Crick et la photo 51 de Franklin révèlent la double hélice — le plan de la vie.' },
