  se_magnus_ladulas: { n: 'Magnus III Ladulås', p: 'Stockholm', d: '« Cadenas du grenier » : prit la couronne à son frère et accorda aux nobles l’exemption d’impôt pour service de cavalerie (Alsnö, 1280).' },
  se_birger: { n: 'Birger Magnusson', p: 'Stockholm', d: 'La couronne folkung se noyant dans les querelles familiales — emprisonna ses frères, fut déposé par eux, mourut en exil.' },
  se_magnus_ericsson: { n: 'Magnus IV Eriksson', p: 'Stockholm', d: 'Hérita de la Norvège à trois ans et de la Suède à dix-sept — deux couronnes, la Peste noire entre les deux, et toutes deux perdues.' },
  se_albrekt: { n: 'Albrekt de Mecklembourg', p: 'Stockholm', d: 'Le roi allemand des nobles — capturé par Marguerite à Falköping (1389) quand ses Allemands devinrent trop avides.' },
  se_karl_knutsson: { n: 'Karl Knutsson Bonde', p: 'Stockholm', d: 'Le roi séparatiste de la Suède dans les fissures de l’union — trois règnes, la couronne de Norvège pour un an, et l’avenir Bonde commencé.' },
  se_gustav_vasa: { n: 'Gustav I Vasa', p: 'Stockholm', d: 'Le cavalier qui survécut au bain de sang : élu roi à la chute de l’union — fonda l’État, l’Église et la dynastie de la Suède.' },
  se_eric_xiv: { n: 'Erik XIV', p: 'Stockholm', d: 'Poussa la Suède au bord de l’empire en Estonie — puis assassina les nobles Sture à Upsal (1568) ; déposé, empoisonné en prison (1577).' },
  se_johan_iii: { n: 'Johan III', p: 'Stockholm', d: 'Epousa une Jagellon et tira la Suède vers les rites romains — la guerre liturgique que son fils hérita.' },
  se_sigismund: { n: 'Sigismund', p: 'Stockholm', d: 'Roi catholique de la Suède protestante : déposé par son oncle à Stångebro (1598) — conserva la Pologne, où sa lignée combattit la Suède un siècle durant.' },
  se_karl_ix: { n: 'Karl IX', p: 'Upsal, Suède', d: 'L’oncle régent qui fit de la régence une institution : écrasa Sigismund, enfin couronné (1607), remit l’empire à son fils.' },
  se_kristina: { n: 'Kristina', p: 'Stockholm', d: 'La reine philosophe de la paix de Westphalie — abdiqua, se convertit à Rome et mourut à Rome parmi ses livres.' },
  se_karl_x_gustav: { n: 'Karl X Gustav', p: 'Stockholm', d: 'Marcha avec une armée sur les Belts gelés jusqu’à Copenhague (1658) — la Suède à sa plus grande largeur, le Danemark coupé en deux par le traité.' },
  se_karl_xi: { n: 'Karl XI', p: 'Stockholm', d: 'Le Réducteur : reprit à la noblesse les terres de la couronne — l’armée caroline et l’État absolu furent son œuvre.' },
  se_karl_xii: { n: 'Karl XII', p: 'Stockholm', d: 'Le dernier Carolinien : Narva à dix-huit ans, Poltava à vingt-six, une balle à Fredriksten (1718) — l’empire mourut avec lui.' },
  se_ulrika_eleonora: { n: 'Ulrika Eleonora', p: 'Stockholm', d: 'Élue reine à condition d’accepter la nouvelle constitution des nobles — abdiqua en un an pour son époux hessois.' },
  se_fredrik_i: { n: 'Frédéric Ier de Hesse', p: 'Stockholm', d: 'Le roi de façade de l’Ère de la Liberté — Chapeaux et Bonnets gouvernaient pendant qu’il chassait.' },
  se_adolf_fredrik: { n: 'Adolf Fredrik', p: 'Stockholm', d: 'Le roi évêque de Lübeck installé par les Chapeaux — mort, dit la légende, d’un festin de desserts.' },
  se_gustav_iii: { n: 'Gustav III', p: 'Stockholm', d: 'Le roi théâtre : son coup de 1772 restaura le pouvoir royal — réforma, se querella et fut abattu à un bal masqué ; Verdi en fit un opéra.' },
  se_gustav_iv_adolf: { n: 'Gustav IV Adolphe', p: 'Stockholm', d: 'L’idéaliste têtu : perdit la Finlande face à la Russie (1809) et son trône dans le coup d’État de la même année.' },
  se_karl_xiii: { n: 'Karl XIII', p: 'Stockholm', d: 'Le vieux roi sans enfants qui adopta un maréchal français — la lignée Bernadotte règne encore.' },
  se_karl_xiv_johan: { n: 'Karl XIV Johan (Bernadotte)', p: 'Stockholm', d: 'Maréchal napoléonien — prince héritier — roi : changea de camp, prit la Norvège en 1814, fonda la dynastie.' },
  se_oskar_i: { n: 'Oskar Ier', p: 'Stockholm', d: 'Le Bernadotte doux : libéralisa l’union, bâtit le premier chemin de fer suédois, resta hors de la guerre de Crimée.' },
  se_karl_xv: { n: 'Karl XV', p: 'Stockholm', d: 'Roi poète et peintre, roi du scandinavisme — l’union avec la Norvège se desserra mais tint.' },
  se_oskar_ii: { n: 'Oskar II', p: 'Stockholm', d: 'Le dernier maître de l’union : en 1905 il laissa la Norvège partir sans un coup de feu — le monarque constitutionnel modèle de l’Europe.' },
  se_gustaf_v: { n: 'Gustaf V', p: 'Stockholm', d: 'Cinq décennies : roi tennisman, neutre à travers deux guerres mondiales, courtisan d’une Suède modernisante.' },
  se_gustaf_vi_adolf: { n: 'Gustaf VI Adolf', p: 'Stockholm', d: 'Le roi archéologue : fouilles étrusques et correction constitutionnelle à travers trois décennies de réformes.' },
  se_carl_xvi_gustaf: { n: 'Carl XVI Gustaf', p: 'Stockholm', d: 'Roi depuis 1973 — chef d’État cérémonial sous la constitution de 1974, la moderne figure de grand-père des Bernadotte.' }
