  fr_rois_faineants: { n: 'Les rois fainéants', p: 'Soissons, France', d: 'De Clovis II à Childéric III, les rois fainéants aux longues chevelures signaient ce que leurs maires du palais leur tendaient ; Charles Martel gouvernait — et son fils coupa la dernière chevelure en 751.' },
  fr_pepin: { n: 'Pépin le Bref', p: 'Soissons, France', d: 'Le maire du palais devenu roi avec la bénédiction papale (751) — recouronné par le Pape (754), il donna à Rome les terres qui devinrent les États pontificaux.' },
  fr_louis_pious: { n: 'Louis le Pieux', p: 'Aix-la-Chapelle', d: 'Héritier de Charlemagne et empereur d’Occident : pénitent, chantant, voué à la réforme — les guerres civiles de ses fils dissolurent l’empire qu’il gardait.' },
  fr_charles_bald: { n: 'Charles II le Chauve', p: 'Paris', d: 'La Francie occidentale après le partage de Verdun (843) : il se battit avec ses frères pour une couronne de débris — couronné empereur à Rome (875), mort en traversant les Alpes.' },
  fr_louis_stammerer: { n: 'Louis II le Bègue', p: 'Paris', d: 'Deux fois couronné et deux fois veuf, il régna vingt mois — deux petits fils héritèrent d’un royaume qui s’affaiblissait.' },
  fr_louis_iii_carloman: { n: 'Louis III et Carloman II', p: 'Paris', d: 'Deux rois enfants contre les Vikings : Louis gagna la bataille chantée de Saucourt (881) — tous deux morts adolescents en cinq ans.' },
  fr_charles_fat: { n: 'Charles III le Gros', p: 'Paris', d: 'Réunit un instant l’empire de Charlemagne, acheta le siège viking de Paris (886) — et fut déposé pour faiblesse par son propre neveu.' },
  fr_odo: { n: 'Eudes de Paris — le premier non Carolingien', p: 'Paris', d: 'Le comte de Paris qui défendit la ville du siège viking (885–86) : les grands le couronnèrent — le premier goût de la couronne pour la lignée Robertienne.' },
  fr_charles_simple: { n: 'Charles III le Simple', p: 'Laon, France', d: 'Couronné à dix-neuf ans face à Eudes : céda la Normandie au chef viking Rollon (911) — puis emprisonné par ses propres barons jusqu’à la mort.' },
  fr_robert_i: { n: 'Robert Ier', p: 'Paris', d: 'Frère d’Eudes, élu roi contre Charles le Simple — tué au combat contre les mêmes envahisseurs contre lesquels il avait lutté toute sa vie (Soissons, 923).' },
