  fr_louis_iv: { n: 'Louis IV d’Outremer', p: 'Paris', d: '« D’outre-mer » — élevé en Angleterre, restauré par Hugues le Grand : la dernière vraie tentative des Carolingiens de régner — contre leurs propres vassaux.' },
  fr_lothair: { n: 'Lothaire', p: 'Paris', d: 'L’avant-dernier Carolingien : trente-deux ans à tenir le royaume entre l’empire d’Otton et les Robertins montants.' },
  fr_louis_v: { n: 'Louis V le Fainéant', p: 'Paris', d: 'Le dernier Carolingien : couronné par son père, mort dans l’année d’une chute de chasse — « le Fainéant », épitaphe de la lignée.' },
  fr_hugh_capet: { n: 'Hugues Capet', p: 'Paris', d: 'Le duc des Francs élu roi quand les Carolingiens s’éteignirent (987) — son comté modeste donna son nom à une dynastie de huit siècles.' },
  fr_robert_ii: { n: 'Robert II le Pieux', p: 'Paris', d: 'Le chrétien zélé qui s’excommunia par son mariage — bûchers d’hérétiques, un royaume grandi par dot, et la première association au trône pour son fils.' },
  fr_henry_i_fr: { n: 'Henri Ier de France', p: 'Paris', d: 'Couronné du vivant de son père : il lutta contre sa mère et son frère rebelles — et aida le jeune Guillaume à gouverner la Normandie avant que la Normandie ne conquît l’Angleterre.' },
  fr_philip_i: { n: 'Philippe Ier', p: 'Paris', d: 'Le premier à se dire « roi de France » — long règne avide et corpulent : excommunié pour son mariage bigame, il transmit pourtant le royaume entier.' },
  fr_louis_vi: { n: 'Louis VI le Gros', p: 'Paris', d: 'Le guerrier qui dompta les seigneurs brigands de l’Île-de-France château par château — et chargea Suger, le grand chroniqueur, de l’écrire.' },
  fr_louis_vii: { n: 'Louis VII le Jeune', p: 'Paris', d: 'Partit en deuxième croisade et revint sans sa reine, Aliénor d’Aquitaine — dont le remariage doubla l’empire Plantagenêt.' },
  fr_philip_ii: { n: 'Philippe II Auguste', p: 'Paris', d: 'Le conquérant : Bouvines (1214), la Normandie et l’Anjou pris au roi Jean — le roi qui fit de la tache féodale le royaume le plus riche d’Europe.' },
  fr_louis_viii: { n: 'Louis VIII le Lion', p: 'Paris', d: 'Croisé contre les cathares du sud — mort au retour d’une campagne qui lui eût presque donné la Gascogne anglaise.' },
  fr_louis_ix: { n: 'Louis IX — Saint Louis', p: 'Paris', d: 'Le roi juste : deux croisades, deux désastres ; mort de peste devant Tunis (1270) — canonisé, modèle de la royauté médiévale.' },
  fr_philip_iii: { n: 'Philippe III le Hardi', p: 'Paris', d: 'Hérita de la croisade où mourut son père — se replia d’Aragon dans une retraite qui tua plus par dysenterie qu’au combat.' },
  fr_philip_iv: { n: 'Philippe IV le Bel', p: 'Paris', d: 'Le roi de fer : brisa Boniface VIII, anéantit les Templiers (1307), pressura les Juifs — et mourut à la chasse, la malédiction du Temple résonnant.' },
  fr_louis_x: { n: 'Louis X le Hutin', p: 'Paris', d: 'Dix-huit mois de fêtes et de chartes serviles — mort à vingt-six ans après une partie de jeu de paume, laissant une reine enceinte.' },
