  fr_charles_iv_fr: { n: 'Charles IV le Bel', p: 'Paris', d: 'Le dernier Capétien direct : mort sans fils et avec une reine enceinte — la crise successorale qui ouvrit la guerre de Cent Ans.' },
  fr_philip_vi: { n: 'Philippe VI de Valois', p: 'Paris', d: 'Le cousin choisi contre Édouard III — dont la contre-prétention alluma la guerre de Cent Ans ; battu à Crécy et perdu Calais (1347).' },
  fr_john_ii: { n: 'Jean II le Bon', p: 'Paris', d: 'Capturé à Poitiers (1356) — revint de sa honorable captivité anglaise pour mourir, car un prince qui manquait à sa parole n’était pas prince.' },
  fr_charles_v: { n: 'Charles V le Sage', p: 'Paris', d: 'Reconquit tout par la guerre d’embuscades et Bertrand du Guesclin — bâtit la Bastille et la bibliothèque royale, mourant méfiant de tous.' },
