  fr_henry_vi_fr: { n: 'Henri VI d’Angleterre — roi de France', p: 'Paris', d: 'Le traité de Troyes fit du nourrisson anglais roi de France (1422) : dix ans de double monarchie — jusqu’à ce qu’une paysanne de Domrémy la brisât.' },
  fr_charles_vii: { n: 'Charles VII — le bien servi', p: 'Paris', d: 'Couronné à Reims grâce à Jeanne d’Arc : acheva la guerre de Cent Ans à Castillon (1453) — livra Jeanne au feu, puis la réhabilita.' },
  fr_louis_xi: { n: 'Louis XI — l’universelle aragne', p: 'Paris', d: 'Rusé sous un chapeau rampant : brisa Charles le Téméraire à Nancy (1477), fila la poste, l’imprimerie — et une toile de peur.' },
  fr_charles_viii: { n: 'Charles VIII', p: 'Paris', d: 'L’affable jeune roi qui envahit l’Italie (1494) — mort à vingt-huit ans, la tête heurtée à un linteau, sans enfants.' },
