  fr_henry_ii_fr: { n: 'Henri II', p: 'Paris', d: 'Le roi de Diane de Poitiers : persécuta les hérétiques par la Chambre Ardente — mourut d’une lance éclatée dans l’œil au tournoi du mariage de sa fille (1559).' },
  fr_francis_ii: { n: 'François II', p: 'Paris', d: 'Le roi enfant maladif marié à Marie Stuart — les frères de Guise gouvernèrent en son nom ; mort à seize ans, un abcès à l’oreille.' },
