  fr_louis_xvi: { n: 'Louis XVI', p: 'Versailles, France', d: 'Le roi serrurier qui voulut être bon : convoqua les États généraux et perdit la maîtrise de la Révolution — guillotiné le 21 janvier 1793.' },
  fr_louis_xviii: { n: 'Louis XVIII', p: 'Paris', d: 'Le comte de Provence goutteux revenu après Napoléon : octroya la Charte constitutionnelle — régna à travers l’interruption des Cent-Jours.' },
  fr_charles_x: { n: 'Charles X', p: 'Paris', d: 'Le frère ultraroyaliste : sacre aux rites médiévaux, censure et indemnités — la révolution de Juillet 1830 l’expédia en exil.' },
